function parseEventStreamBlock(block) {
  const lines = String(block || "").split(`
`);
  let event = "message";
  const dataLines = [];
  for (const line of lines) {
    if (line.startsWith("event:")) {
      event = line.slice(6).trim() || "message";
    } else if (line.startsWith("data:")) {
      dataLines.push(line.slice(5).trim());
    }
  }
  const rawData = dataLines.join(`
`);
  if (!rawData)
    return null;
  try {
    return { event, data: JSON.parse(rawData) };
  } catch {
    return { event, data: rawData };
  }
}
async function consumeEventStream(response, onEvent) {
  if (!response.body)
    throw new Error("Missing event stream body");
  const reader = response.body.getReader();
  const decoder = new TextDecoder;
  let buffer = "";
  while (true) {
    const { value, done } = await reader.read();
    if (done)
      break;
    buffer += decoder.decode(value, { stream: true });
    const parts = buffer.split(`

`);
    buffer = parts.pop() || "";
    for (const part of parts) {
      const parsed = parseEventStreamBlock(part);
      if (parsed)
        onEvent(parsed.event, parsed.data);
    }
  }
  buffer += decoder.decode();
  const tail = parseEventStreamBlock(buffer);
  if (tail)
    onEvent(tail.event, tail.data);
}
