    const measuredOverflow = panelKey === "thought" || panelKey === "draft" ? previewOverflow.overflow[panelKey] : Boolean(panelKey && overflowingPanels[panelKey]);
    const hasOverflow = estimatedOverflow || measuredOverflow;
